import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Typography } from 'antd';
import cn from 'classnames';

import ChartIcon from 'assets/images/icons/chart.svg?react';
import { useMedia } from 'shared/hooks';
import { formatNumber } from 'shared/utils';

import styles from './BalanceItem.module.scss';

interface IBalanceItemProps extends HTMLAttributes<HTMLDivElement> {
	balance: string;
	currency: string;
	type: 'available' | 'approve' | 'hold';
	currenciesMap: Record<string, string>;
	reportsLink?: string;
}

interface IType {
	color: string;
	title: string;
}

export const BalanceItem: FC<IBalanceItemProps> = ({
	className,
	balance,
	currency,
	type,
	currenciesMap,
	reportsLink,
	...props
}) => {
	const { t } = useTranslation();
	const isMobile = useMedia();

	const types: Record<typeof type, IType> = {
		available: {
			color: '#009cf4',
			title: t('Available for withdrawal'),
		},
		approve: {
			color: '#8990a1',
			title: t('Approved waiting for advertisers payment'),
		},
		hold: {
			color: '#8990a1',
			title: t('On hold'),
		},
	};

	return (
		<div {...props} className={cn(className, styles.balanceItem, styles[type])}>
			<div className={styles.info}>
				<Typography.Text className={styles.title}>{types[type].title}</Typography.Text>

				<Typography.Text className={styles.balance}>
					{isMobile && currenciesMap[currency]} {formatNumber(balance)} {!isMobile && currency}
				</Typography.Text>
			</div>

			<div className={styles.icon}>
				<Typography.Link href={reportsLink}>
					<ChartIcon />
				</Typography.Link>
			</div>
		</div>
	);
};
