import { FC, HTMLAttributes } from 'react';
import { HashLink } from 'react-router-hash-link';

import { Button, Modal, Typography } from 'antd';
import cn from 'classnames';

import WithdrawalIcon from 'assets/images/icons/withdrawal.svg?react';
import { ERawReportStatuses } from 'entities/Report';
import { EFilters } from 'features/Filters';
import { EMainRoutes } from 'shared/typings';
import { formatNumber } from 'shared/utils';

import { useBalance } from '../../hooks/useBalance';
import { BalanceItem } from '../BalanceItem/BalanceItem';
import { Withdrawal } from '../Withdrawal/Withdrawal';

import styles from './Balance.module.scss';

interface IBalanceProps extends HTMLAttributes<HTMLDivElement> {
	type?: 'short' | 'extend';
}

export const Balance: FC<IBalanceProps> = ({ className, type = 'short', ...props }) => {
	const {
		t,
		isMobile,
		modalIsOpen,
		appConfig,
		currenciesMap,
		isLoading,
		checkedWithdrawal,
		addTransaction,
		setModalIsOpen,
	} = useBalance();

	if (!appConfig?.user?.balance) {
		return null;
	}

	const {
		user: {
			balance: { approved_amount, balance_amount, on_hold_amount, currency },
		},
	} = appConfig;

	if (type === 'short') {
		const balanceHoldSumm = (Number(approved_amount) || 0) + (Number(on_hold_amount) || 0);

		return (
			<div {...props} className={cn(className, styles.short)}>
				<Typography.Text type="success" strong>
					{currency}
				</Typography.Text>
				<Typography.Text type="success" strong>
					{formatNumber(balance_amount)}
				</Typography.Text>
				<Typography.Text type="secondary" className={styles.separ}>
					/
				</Typography.Text>
				<Typography.Text type="secondary" className={styles.total}>
					{formatNumber(balanceHoldSumm)}
				</Typography.Text>
			</div>
		);
	}

	if (type === 'extend') {
		return (
			<>
				<Modal open={modalIsOpen} onCancel={() => setModalIsOpen(false)} destroyOnHidden footer={null}>
					<Withdrawal withdrawal={checkedWithdrawal} currency={currency} />
				</Modal>
				<div {...props} className={cn(className, styles.extend)}>
					<div className={styles.balance}>
						<BalanceItem type="available" balance={balance_amount} currency={currency} currenciesMap={currenciesMap} />
						<BalanceItem
							type="approve"
							balance={approved_amount}
							currency={currency}
							currenciesMap={currenciesMap}
							reportsLink={`/${EMainRoutes.REPORTS}?${EFilters.STATUS}=${ERawReportStatuses.APPROVED}`}
						/>
						<BalanceItem
							type="hold"
							balance={on_hold_amount}
							currency={currency}
							currenciesMap={currenciesMap}
							reportsLink={`/${EMainRoutes.REPORTS}?${EFilters.STATUS}=${ERawReportStatuses.ON_HOLD}`}
						/>
					</div>

					<div className={styles.buttons}>
						<Button
							icon={<WithdrawalIcon />}
							onClick={() => addTransaction()}
							size="large"
							block={isMobile}
							type={'primary'}
							disabled={isLoading || !appConfig.payouts_available || !Number(balance_amount)}
							loading={isLoading}>
							{t('Send to wallet')}, {balance_amount} {currency}
						</Button>

						<HashLink to="#faq">
							<Button size="large">{t('How withdrawals work?')}</Button>
						</HashLink>
					</div>
				</div>
			</>
		);
	}
};
